service.method:

		MERGE INTO SCMGL
		USING (SELECT '' A) DUAL ON 
		     (	  HOUSE_CODE   = ${session.HOUSE_CODE}
		  	  AND COMPANY_CODE = ${COMPANY_CODE}
		  	 )
		 WHEN MATCHED 
		 THEN UPDATE                                                        
		         SET LANGUAGE 	 	            = ${LANGUAGE}
					,COMPANY_NAME_LOC           = ${COMPANY_NAME_LOC}      
					,COMPANY_NAME_ENG           = ${COMPANY_NAME_ENG}      
					,CUR                        = ${CUR}      
					,COUNTRY                    = ${COUNTRY}      
					,CITY_CODE                  = ${CITY_CODE}      
					,IRS_NO                     = ${IRS_NO}      
					,DUNS_NO                    = ${DUNS_NO}      
					,FOUNDATION_DATE            = ${FOUNDATION_DATE}      
					,GROUP_COMPANY_CODE         = ${GROUP_COMPANY_CODE}      
					,GROUP_COMPANY_NAME         = ${GROUP_COMPANY_NAME}      
					,CREDIT_RATING              = ${CREDIT_RATING}      
					,INDUSTRY_TYPE              = ${INDUSTRY_TYPE}        
					,BUSINESS_TYPE              = ${BUSINESS_TYPE}      
					,TRADE_AGENCY_NO            = ${TRADE_AGENCY_NO}      
					,TRADE_AGENCY_NAME          = ${TRADE_AGENCY_NAME}      
					,EDI_ID                     = ${EDI_ID}      
					,EDI_QUALIFIER              = ${EDI_QUALIFIER}      
					,INS_COM_CODE               = ${INS_COM_CODE}   
					,CHANGE_DATE     = ${current.date}      
					,CHANGE_TIME     = ${current.time}
					,CHANGE_USER_ID  = ${session.ID}   
	   	 WHEN NOT MATCHED 
	     THEN INSERT(HOUSE_CODE
	                ,COMPANY_CODE
	                ,LANGUAGE 	 	   
			        ,COMPANY_NAME_LOC  
			        ,COMPANY_NAME_ENG  
			        ,CUR               
			        ,COUNTRY           
			        ,CITY_CODE         
			        ,IRS_NO            
			        ,DUNS_NO           
			        ,FOUNDATION_DATE   
			        ,GROUP_COMPANY_CODE
			        ,GROUP_COMPANY_NAME
			        ,CREDIT_RATING     
			        ,INDUSTRY_TYPE     
			        ,BUSINESS_TYPE     
			        ,TRADE_AGENCY_NO   
			        ,TRADE_AGENCY_NAME 
			        ,EDI_ID            
			        ,EDI_QUALIFIER     
			        ,INS_COM_CODE
			        ,CHANGE_DATE    
	                ,CHANGE_TIME    
	                ,CHANGE_USER_ID 
	                ,ADD_DATE   
	                ,ADD_TIME   
	                ,ADD_USER_ID       
	     	)VALUES(
	     	        ${session.HOUSE_CODE}
	     	       ,${COMPANY_CODE}
	     		   ,${LANGUAGE}          
			       ,${COMPANY_NAME_LOC}  
			       ,${COMPANY_NAME_ENG}  
			       ,${CUR}               
			       ,${COUNTRY}           
			       ,${CITY_CODE}         
			       ,${IRS_NO}            
			       ,${DUNS_NO}           
			       ,${FOUNDATION_DATE}   
			       ,${GROUP_COMPANY_CODE}
			       ,${GROUP_COMPANY_NAME}
			       ,${CREDIT_RATING}     
			       ,${INDUSTRY_TYPE}     
			       ,${BUSINESS_TYPE}     
			       ,${TRADE_AGENCY_NO}   
			       ,${TRADE_AGENCY_NAME} 
			       ,${EDI_ID}            
			       ,${EDI_QUALIFIER}     
			       ,${INS_COM_CODE}   
			       ,${current.date}    
                   ,${current.time}    
                   ,${session.ID}
                   ,${current.date}    
                   ,${current.time}    
                   ,${session.ID}   
	     	)


		MERGE INTO SADDR
		USING (SELECT '' A) DUAL ON 
		     (	  HOUSE_CODE   = ${session.HOUSE_CODE}
		  	  AND CODE_NO      = ${CODE_NO}
		  	  AND CODE_TYPE    = ${CODE_TYPE}
		  	 )
		 WHEN MATCHED 
		 THEN UPDATE                                                        
		         SET ADDRESS_LOC  = ${ADDRESS_LOC}                                
			        ,ADDRESS_ENG  = ${ADDRESS_ENG}                               
			        ,ZIP_CODE     = ${ZIP_CODE}
			        ,HOMEPAGE     = ${HOMEPAGE}
			        ,PHONE_NO1	  = ${PHONE_NO}
			        ,CEO_NAME_LOC = ${CEO_NAME}
			        ,CHANGE_DATE     = ${current.date}      
					,CHANGE_TIME     = ${current.time}
					,CHANGE_USER_ID  = ${session.ID} 
	   	 WHEN NOT MATCHED 
	     THEN INSERT(HOUSE_CODE
	                ,CODE_NO
	                ,CODE_TYPE
	                ,ADDRESS_LOC 
					,ADDRESS_ENG 
					,ZIP_CODE    
					,HOMEPAGE    
					,PHONE_NO1	 
					,CEO_NAME_LOC     
					,CHANGE_DATE    
	                ,CHANGE_TIME    
	                ,CHANGE_USER_ID 
	                ,ADD_DATE   
	                ,ADD_TIME   
	                ,ADD_USER_ID 
	     	)VALUES(
	     	        ${session.HOUSE_CODE}
	     	       ,${CODE_NO}
	     	       ,${CODE_TYPE}
	     	 	   ,${ADDRESS_LOC}
			       ,${ADDRESS_ENG}
			       ,${ZIP_CODE}   
			       ,${HOMEPAGE}   
			       ,${PHONE_NO}   
			       ,${CEO_NAME}
			       ,${current.date}    
                   ,${current.time}    
                   ,${session.ID}
                   ,${current.date}    
                   ,${current.time}    
                   ,${session.ID}
	     	)


		MERGE INTO SPLNT
		USING (SELECT '' A) DUAL ON 
		     (	  HOUSE_CODE   = ${session.HOUSE_CODE}
		  	  AND COMPANY_CODE = ${COMPANY_CODE}
		  	  AND PLANT_CODE = ${PLANT_CODE}
		  	 )
		 WHEN MATCHED 
		 THEN UPDATE                                                        
		  SET PLANT_NAME_LOC  = ${PLANT_NAME_LOC}    
			 ,PLANT_NAME_ENG  = ${PLANT_NAME_ENG}
			 ,COUNTRY         = ${COUNTRY}        
			 ,DEPT            = ${DEPT}           
			 ,LOGISTICS_AREA  = ${LOGISTICS_AREA} 
			 ,IRS_NO          = ${IRS_NO}         
			 ,PR_LOCATION     = ${PR_LOCATION}      
			 ,INDUSTRY_TYPE   = ${INDUSTRY_TYPE}       
			 ,BUSINESS_TYPE   = ${BUSINESS_TYPE}       
			 ,BIZ_NAME_LOC    = ${BIZ_NAME_LOC}   
			 ,BIZ_NAME_ENG    = ${BIZ_NAME_ENG}     
			 ,ATTACH_NO       = ${ATTACH_NO}      
			 ,CHANGE_DATE     = ${current.date}      
			 ,CHANGE_TIME     = ${current.time}
			 ,CHANGE_USER_ID  = ${session.ID}                           
	   	 WHEN NOT MATCHED 
	     THEN INSERT(HOUSE_CODE         
					,COMPANY_CODE
					,PLANT_CODE 
				    ,PLANT_NAME_LOC 					
	                ,PLANT_NAME_ENG 
	                ,COUNTRY        
	                ,LOGISTICS_AREA 
	                ,IRS_NO         
	                ,PR_LOCATION    
	                ,INDUSTRY_TYPE  
	                ,BUSINESS_TYPE  
	                ,BIZ_NAME_LOC   
	                ,BIZ_NAME_ENG   
	                ,ATTACH_NO      
	                ,CHANGE_DATE    
	                ,CHANGE_TIME    
	                ,CHANGE_USER_ID 
	                ,ADD_DATE   
	                ,ADD_TIME   
	                ,ADD_USER_ID
			)VALUES( 
			         ${session.HOUSE_CODE}     
			        ,${COMPANY_CODE}   
			        ,${PLANT_CODE}     
			        ,${PLANT_NAME_LOC} 
			        ,${PLANT_NAME_ENG} 
			        ,${COUNTRY}        
			        ,${LOGISTICS_AREA} 
			        ,${IRS_NO}         
			        ,${PR_LOCATION}    
			        ,${INDUSTRY_TYPE}  
			        ,${BUSINESS_TYPE}  
			        ,${BIZ_NAME_LOC}   
			        ,${BIZ_NAME_ENG}   
			        ,${ATTACH_NO}      
			        ,${current.date}    
                    ,${current.time}    
                    ,${session.ID}
                    ,${current.date}    
                    ,${current.time}    
                    ,${session.ID}
			)


		MERGE INTO SDEPT
		USING (SELECT '' A) DUAL ON 
		     (	  HOUSE_CODE   = ${session.HOUSE_CODE}
		  	  AND COMPANY_CODE = ${COMPANY_CODE}
		  	  AND DEPT 		   = ${DEPT}
		  	 )
		 WHEN MATCHED 
		 THEN UPDATE   
	 	  SET DEPT_NAME_LOC     = ${DEPT_NAME_LOC}
             ,DEPT_NAME_ENG     = ${DEPT_NAME_ENG}
             ,MANAGER_NAME      = ${MANAGER_NAME}
             ,MANAGER_POSITION  = ${MANAGER_POSITION}
             ,PR_LOCATION       = ${PR_LOCATION}
             ,PR_LOCATION_NAME  = ${PR_LOCATION_NAME}
             ,CTRL_DEPT_FLAG    = ${CTRL_DEPT_FLAG}
             ,PHONE_NO          = ${PHONE_NO}
             ,FAX_NO            = ${FAX_NO}
             ,MENU_TYPE         = ${MENU_TYPE}
             ,WORK_TYPE         = ${WORK_TYPE}
             ,MENU_PROFILE_CODE = ${MENU_PROFILE_CODE}
             ,SIGN_ATTACH_NO    = ${SIGN_ATTACH_NO}
             ,PARENT_DEPT       = ${PARENT_DEPT}
             ,MANAGER_ID        = ${MANAGER_ID}
             ,DPC               = ${DPC}
             ,DPTSNA            = ${DPTSNA}
             ,DPTCNA            = ${DPTCNA}
             ,DPTCL             = ${DPTCL}
             ,DPTJL             = ${DPTJL}
             ,SAUP              = ${SAUP}             
         	 ,CHANGE_DATE       = ${current.date}      
			 ,CHANGE_TIME       = ${current.time}
			 ,CHANGE_USER_ID    = ${session.ID} 
		 WHEN NOT MATCHED 
	     THEN INSERT(HOUSE_CODE  
	                ,COMPANY_CODE
	                ,DEPT 		  
	                ,DEPT_NAME_LOC    
	                ,DEPT_NAME_ENG    
	                ,MANAGER_NAME     
	                ,MANAGER_POSITION 
	                ,PR_LOCATION      
	                ,PR_LOCATION_NAME 
	                ,CTRL_DEPT_FLAG   
	                ,PHONE_NO         
	                ,FAX_NO           
	                ,MENU_TYPE        
	                ,WORK_TYPE        
	                ,MENU_PROFILE_CODE
	                ,SIGN_ATTACH_NO   
	                ,PARENT_DEPT      
	                ,MANAGER_ID       
	                ,DPC              
	                ,DPTSNA           
	                ,DPTCNA           
	                ,DPTCL            
	                ,DPTJL            
	                ,SAUP             
	                ,CHANGE_DATE      
	                ,CHANGE_TIME      
	                ,CHANGE_USER_ID   
	                ,ADD_DATE      
	                ,ADD_TIME      
	                ,ADD_USER_ID   
	      	 )VALUES(${session.HOUSE_CODE}       
			        ,${COMPANY_CODE}     
			        ,${DEPT} 		      
			        ,${DEPT_NAME_LOC}    
			        ,${DEPT_NAME_ENG}    
			        ,${MANAGER_NAME}     
			        ,${MANAGER_POSITION} 
			        ,${PR_LOCATION}      
			        ,${PR_LOCATION_NAME} 
			        ,${CTRL_DEPT_FLAG}   
			        ,${PHONE_NO}         
			        ,${FAX_NO}           
			        ,${MENU_TYPE}        
			        ,${WORK_TYPE}        
			        ,${MENU_PROFILE_CODE}
			        ,${SIGN_ATTACH_NO}   
			        ,${PARENT_DEPT}      
			        ,${MANAGER_ID}       
			        ,${DPC}              
			        ,${DPTSNA}           
			        ,${DPTCNA}           
			        ,${DPTCL}            
			        ,${DPTJL}
			        ,${SAUP}             
			        ,${current.date}     
			        ,${current.time}    
			        ,${session.ID}   
			        ,${current.date}     
			        ,${current.time}    
			        ,${session.ID} 
			)


	MERGE INTO SBAGL
	USING (SELECT '' A) DUAL ON 
	     (	  HOUSE_CODE   = ${session.HOUSE_CODE}
	  	  AND COMPANY_CODE = ${COMPANY_CODE}
	  	  AND CTRL_CODE	   = ${CTRL_CODE}
	  	 )
	 WHEN MATCHED 
	 THEN UPDATE   
	  SET CTRL_NAME_LOC   = ${CTRL_NAME_LOC}
	     ,CTRL_NAME_ENG   = ${CTRL_NAME_ENG}
	     ,CHANGE_DATE     = ${current.date}
		 ,CHANGE_TIME     = ${current.time}
		 ,CHANGE_USER_ID  = ${session.ID}                                                      
   	 WHEN NOT MATCHED 
     THEN INSERT(HOUSE_CODE      
				,COMPANY_CODE    
				,CTRL_CODE       
				,CTRL_NAME_LOC   
				,CTRL_NAME_ENG   
				,CHANGE_DATE
				,CHANGE_TIME
				,CHANGE_USER_ID
				,ADD_DATE
				,ADD_TIME
				,ADD_USER_ID
		)VALUES( 
		         ${session.HOUSE_CODE}    
		        ,${COMPANY_CODE}  
		        ,${CTRL_CODE}     
		        ,${CTRL_NAME_LOC} 
		        ,${CTRL_NAME_ENG} 
		        ,${current.date}
		        ,${current.time} 
		        ,${session.ID}  
		        ,${current.date}   
		        ,${current.time}   
		        ,${session.ID}     
		);


		MERGE INTO SSTRG
		USING (SELECT '' A) DUAL ON 
		     (	  HOUSE_CODE   = ${session.HOUSE_CODE}
		  	  AND COMPANY_CODE = ${COMPANY_CODE}
		  	  AND PLANT_CODE   = ${PLANT_CODE}
		  	  AND STORAGE_CODE = ${STORAGE_CODE}
		  	 )
		 WHEN MATCHED 
		 THEN UPDATE   
		  SET STORAGE_NAME_LOC = ${STORAGE_NAME_LOC}  
		     ,STORAGE_NAME_ENG = ${STORAGE_NAME_ENG}
		     ,COUNTRY          = ${COUNTRY}
		     ,DEPT             = ${DEPT}
		     ,LOGISTICS_AREA   = ${LOGISTICS_AREA}
		     ,IRS_NO           = ${IRS_NO}
		     ,INDUSTRY_TYPE    = ${INDUSTRY_TYPE}
		     ,BUSINESS_TYPE    = ${BUSINESS_TYPE}
		     ,BIZ_NAME_LOC     = ${BIZ_NAME_LOC}
		     ,BIZ_NAME_ENG     = ${BIZ_NAME_ENG}
		     ,CHANGE_DATE     = ${current.date}
			 ,CHANGE_TIME     = ${current.time}
			 ,CHANGE_USER_ID  = ${session.ID}      
	   	 WHEN NOT MATCHED 
	     THEN INSERT(HOUSE_CODE  
					,COMPANY_CODE
					,PLANT_CODE  
					,STORAGE_CODE
					,STORAGE_NAME_LOC
					,STORAGE_NAME_ENG
					,COUNTRY         
					,LOGISTICS_AREA  
					,IRS_NO          
					,INDUSTRY_TYPE   
			        ,BUSINESS_TYPE   
			        ,BIZ_NAME_LOC    
			        ,BIZ_NAME_ENG    
			        ,CHANGE_DATE
					,CHANGE_TIME
					,CHANGE_USER_ID
					,ADD_DATE
					,ADD_TIME
					,ADD_USER_ID
			 )VALUES(${session.HOUSE_CODE}       
                    ,${COMPANY_CODE}    
                    ,${PLANT_CODE}      
                    ,${STORAGE_CODE}    
                    ,${STORAGE_NAME_LOC}
                    ,${STORAGE_NAME_ENG}
                    ,${COUNTRY}         
                    ,${LOGISTICS_AREA}  
                    ,${IRS_NO}          
                    ,${INDUSTRY_TYPE}   
                    ,${BUSINESS_TYPE}   
                    ,${BIZ_NAME_LOC}    
			        ,${BIZ_NAME_ENG}
			        ,${current.date}
			        ,${current.time} 
			        ,${session.ID}  
			        ,${current.date}   
			        ,${current.time}   
			        ,${session.ID}  
			 )


DELETE SCMGL
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}


DELETE SPLNT
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND PLANT_CODE = ${PLANT_CODE}


DELETE SADDR
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND CODE_NO   = ${CODE_NO}
   AND CODE_TYPE = ${CODE_TYPE}


DELETE SDEPT
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND DEPT 		   = ${DEPT}


DELETE SBAGL
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND CTRL_CODE	= ${CTRL_CODE}


DELETE SSTRG
 WHERE HOUSE_CODE   = ${session.HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND PLANT_CODE   = ${PLANT_CODE}
   AND STORAGE_CODE = ${STORAGE_CODE}
